// Bundled food photos. These data URLs work both in VS Code and on GitHub Pages.
const tasteHubPhotos = {
  "seafood-pasta.jpg": "data:image/jpeg;base64,",
  "fresh-off-grill.jpg": "data:image/jpeg;base64,",
  "celebration.jpg": "data:image/jpeg;base64,",
  "fried-rice-grilled-chicken.jpg": "data:image/jpeg;base64,",
  "jollof-rice-chicken.jpg": "data:image/jpeg;base64,",
  "chicken-shawarma.jpg": "data:image/jpeg;base64,",
  "beef-burger.jpg": "data:image/jpeg;base64,"
};
document.querySelectorAll("img[src^='assets/']").forEach((image) => {
  const fileName = image.getAttribute("src").split("/").pop();
  if (tasteHubPhotos[fileName]) image.src = tasteHubPhotos[fileName];
});
const tasteHubLogo = "data:image/jpeg;base64,";
document.querySelectorAll("img[src='assets/taste-hub-logo.jpg']").forEach((image) => { image.src = tasteHubLogo; });

